      .appendingPathComponent(bundleID ?? "com.developwithstyle.workroom", isDirectory: true)
      .appendingPathComponent("unrecognized-tool-usage.json")
  }

  /// Increments the on-disk count for `name` (an executable basename). Fires at most once per new
  /// foreground command (the caller only calls this on a genuine title change), so a synchronous
  /// read-modify-write on the caller's thread is fine — this is not a hot path.
  static func recordUnrecognized(_ name: String, url: URL = defaultURL()) {
    var counts = load(url: url)
    counts[name, default: 0] += 1
    save(counts, url: url)
  }

  private static func load(url: URL) -> [String: Int] {
    guard let data = try? Data(contentsOf: url),
      let decoded = try? JSONDecoder().decode([String: Int].self, from: data)
    else { return [:] }
    return decoded
  }

  private static func save(_ counts: [String: Int], url: URL) {
    do {
      try FileManager.default.createDirectory(
        at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
      let encoder = JSONEncoder()
      encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
      try encoder.encode(counts).write(to: url, options: .atomic)
    } catch {
      logger.error("failed to persist unrecognized-tool-usage.json: \(error, privacy: .public)")
    }
  }
}

